Warning":false,"citationHelpUrl":"https://docs.github.com/github/creating-cloning-and-archiving-repositories/creating-a-repository-on-github/about-citation-files","actionsOnboardingTip":null},"truncated":false,"viewable":true,"workflowRedirectUrl":null},"copilotInfo":null,"copilotAccessAllowed":true,"copilotSpacesEnabled":true,"modelsAccessAllowed":false,"modelsRepoIntegrationEnabled":false,"isMarketplaceEnabled":true},"codeViewBlobLayoutRoute.StyledBlob":{"rawLines":["\u003c?php","/**"," * The Unzipper extracts .zip or .rar archives and .gz files on webservers."," * It's handy if you do not have shell access. E.g. if you want to upload a lot"," * of files (php framework or image collection) as an archive to save time."," * As of version 0.1.0 it also supports creating archives."," *"," * @author  Andreas Tasch, at[tec], attec.at"," * @license GNU GPL v3"," * @package attec.toolbox"," * @version 0.1.1"," */","define('VERSION', '0.1.1');","","$timestart = microtime(TRUE);","$GLOBALS['status'] = array();","","$unzipper = new Unzipper;","if (isset($_POST['dounzip'])) {","  // Check if an archive was selected for unzipping.","  $archive = isset($_POST['zipfile']) ? strip_tags($_POST['zipfile']) : '';","  $destination = isset($_POST['extpath']) ? strip_tags($_POST['extpath']) : '';","  $unzipper-\u003eprepareExtraction($archive, $destination);","}","","if (isset($_POST['dozip'])) {","  $zippath = !empty($_POST['zippath']) ? strip_tags($_POST['zippath']) : '.';","  // Resulting zipfile e.g. zipper--2016-07-23--11-55.zip.","  $zipfile = 'zipper-' . date(\"Y-m-d--H-i\") . '.zip';","  Zipper::zipDir($zippath, $zipfile);","}","","$timeend = microtime(TRUE);","$time = round($timeend - $timestart, 4);","","/**"," * Class Unzipper"," */","class Unzipper {","  public $localdir = '.';","  public $zipfiles = array();","","  public function __construct() {","    // Read directory and pick .zip, .rar and .gz files.","    if ($dh = opendir($this-\u003elocaldir)) {","      while (($file = readdir($dh)) !== FALSE) {","        if (pathinfo($file, PATHINFO_EXTENSION) === 'zip'","          || pathinfo($file, PATHINFO_EXTENSION) === 'gz'","          || pathinfo($file, PATHINFO_EXTENSION) === 'rar'","        ) {","          $this-\u003ezipfiles[] = $file;","        }","      }","      closedir($dh);","","      if (!empty($this-\u003ezipfiles)) {","        $GLOBALS['status'] = array('info' =\u003e '.zip or .gz or .rar files found, ready for extraction');","      }","      else {","        $GLOBALS['status'] = array('info' =\u003e 'No .zip or .gz or rar files found. So only zipping functionality available.');","      }","    }","  }","","  /**","   * Prepare and check zipfile for extraction.","   *","   * @param string $archive","   *   The archive name including file extension. E.g. my_archive.zip.","   * @param string $destination","   *   The relative destination path where to extract files.","   */","  public function prepareExtraction($archive, $destination = '') {","    // Determine paths.","    if (empty($destination)) {","      $extpath = $this-\u003elocaldir;","    }","    else {","      $extpath = $this-\u003elocaldir . '/' . $destination;","      // Todo: move this to extraction function.","      if (!is_dir($extpath)) {","        mkdir($extpath);","      }","    }","    // Only local existing archives are allowed to be extracted.","    if (in_array($archive, $this-\u003ezipfiles)) {","      self::extract($archive, $extpath);","    }","  }","","  /**","   * Checks file extension and calls suitable extractor functions.","   *","   * @param string $archive","   *   The archive name including file extension. E.g. my_archive.zip.","   * @param string $destination","   *   The relative destination path where to extract files.","   */","  public static function extract($archive, $destination) {","    $ext = pathinfo($archive, PATHINFO_EXTENSION);","    switch ($ext) {","      case 'zip':","        self::extractZipArchive($archive, $destination);","        break;","      case 'gz':","        self::extractGzipFile($archive, $destination);","        break;","      case 'rar':","        self::extractRarArchive($archive, $destination);","        break;","    }","","  }","","  /**","   * Decompress/extract a zip archive using ZipArchive.","   *","   * @param $archive","   * @param $destination","   */","  public static function extractZipArchive($archive, $destination) {","    // Check if webserver supports unzipping.","    if (!class_exists('ZipArchive')) {","      $GLOBALS['status'] = array('error' =\u003e 'Error: Your PHP version does not support unzip functionality.');","      return;","    }","","    $zip = new ZipArchive;","","    // Check if archive is readable.","    if ($zip-\u003eopen($archive) === TRUE) {","      // Check if destination is writable","      if (is_writeable($destination . '/')) {","        $zip-\u003eextractTo($destination);","        $zip-\u003eclose();","        $GLOBALS['status'] = array('success' =\u003e 'Files unzipped successfully');","      }","      else {","        $GLOBALS['status'] = array('error' =\u003e 'Error: Directory not writeable by webserver.');","      }","    }","    else {","      $GLOBALS['status'] = array('error' =\u003e 'Error: Cannot read .zip archive.');","    }","  }","","  /**","   * Decompress a .gz File.","   *","   * @param string $archive","   *   The archive name including file extension. E.g. my_archive.zip.","   * @param string $destination","   *   The relative destination path where to extract files.","   */","  public static function extractGzipFile($archive, $destination) {","    // Check if zlib is enabled","    if (!function_exists('gzopen')) {","      $GLOBALS['status'] = array('error' =\u003e 'Error: Your PHP has no zlib support enabled.');","      return;","    }","","    $filename = pathinfo($archive, PATHINFO_FILENAME);","    $gzipped = gzopen($archive, \"rb\");","    $file = fopen($destination . '/' . $filename, \"w\");","","    while ($string = gzread($gzipped, 4096)) {","      fwrite($file, $string, strlen($string));","    }","    gzclose($gzipped);","    fclose($file);","","    // Check if file was extracted.","    if (file_exists($destination . '/' . $filename)) {","      $GLOBALS['status'] = array('success' =\u003e 'File unzipped successfully.');","","      // If we had a tar.gz file, let's extract that tar file.","      if (pathinfo($destination . '/' . $filename, PATHINFO_EXTENSION) == 'tar') {","        $phar = new PharData($destination . '/' . $filename);","        if ($phar-\u003eextractTo($destination)) {","          $GLOBALS['status'] = array('success' =\u003e 'Extracted tar.gz archive successfully.');","          // Delete .tar.","          unlink($destination . '/' . $filename);","        }","      }","    }","    else {","      $GLOBALS['status'] = array('error' =\u003e 'Error unzipping file.');","    }","","  }","","  /**","   * Decompress/extract a Rar archive using RarArchive.","   *","   * @param string $archive","   *   The archive name including file extension. E.g. my_archive.zip.","   * @param string $destination","   *   The relative destination path where to extract files.","   */","  public static function extractRarArchive($archive, $destination) {","    // Check if webserver supports unzipping.","    if (!class_exists('RarArchive')) {","      $GLOBALS['status'] = array('error' =\u003e 'Error: Your PHP version does not support .rar archive functionality. \u003ca class=\"info\" href=\"http://php.net/manual/en/rar.installation.php\" target=\"_blank\"\u003eHow to install RarArchive\u003c/a\u003e');","      return;","    }","    // Check if archive is readable.","    if ($rar = RarArchive::open($archive)) {","      // Check if destination is writable","      if (is_writeable($destination . '/')) {","        $entries = $rar-\u003egetEntries();","        foreach ($entries as $entry) {","          $entry-\u003eextract($destination);","        }","        $rar-\u003eclose();","        $GLOBALS['status'] = array('success' =\u003e 'Files extracted successfully.');","      }","      else {","        $GLOBALS['status'] = array('error' =\u003e 'Error: Directory not writeable by webserver.');","      }","    }","    else {","      $GLOBALS['status'] = array('error' =\u003e 'Error: Cannot read .rar archive.');","    }","  }","","}","","/**"," * Class Zipper"," *"," * Copied and slightly modified from http://at2.php.net/manual/en/class.ziparchive.php#110719"," * @author umbalaconmeogia"," */","class Zipper {","  /**","   * Add files and sub-directories in a folder to zip file.","   *","   * @param string $folder","   *   Path to folder that should be zipped.","   *","   * @param ZipArchive $zipFile","   *   Zipfile where files end up.","   *","   * @param int $exclusiveLength","   *   Number of text to be exclusived from the file path.","   */","  private static function folderToZip($folder, \u0026$zipFile, $exclusiveLength) {","    $handle = opendir($folder);","","    while (FALSE !== $f = readdir($handle)) {","      // Check for local/parent path or zipping file itself and skip.","      if ($f != '.' \u0026\u0026 $f != '..' \u0026\u0026 $f != basename(__FILE__)) {","        $filePath = \"$folder/$f\";","        // Remove prefix from file path before add to zip.","        $localPath = substr($filePath, $exclusiveLength);","","        if (is_file($filePath)) {","          $zipFile-\u003eaddFile($filePath, $localPath);","        }","        elseif (is_dir($filePath)) {","          // Add sub-directory.","          $zipFile-\u003eaddEmptyDir($localPath);","          self::folderToZip($filePath, $zipFile, $exclusiveLength);","        }","      }","    }","    closedir($handle);","  }","","  /**","   * Zip a folder (including itself).","   *","   * Usage:","   *   Zipper::zipDir('path/to/sourceDir', 'path/to/out.zip');","   *","   * @param string $sourcePath","   *   Relative path of directory to be zipped.","   *","   * @param string $outZipPath","   *   Relative path of the resulting output zip file.","   */","  public static function zipDir($sourcePath, $outZipPath) {","    $pathInfo = pathinfo($sourcePath);","    $parentPath = $pathInfo['dirname'];","    $dirName = $pathInfo['basename'];","","    $z = new ZipArchive();","    $z-\u003eopen($outZipPath, ZipArchive::CREATE);","    $z-\u003eaddEmptyDir($dirName);","    if ($sourcePath == $dirName) {","      self::folderToZip($sourcePath, $z, 0);","    }","    else {","      self::folderToZip($sourcePath, $z, strlen(\"$parentPath/\"));","    }","    $z-\u003eclose();","","    $GLOBALS['status'] = array('success' =\u003e 'Successfully created archive ' . $outZipPath);","  }","}","?\u003e","","\u003c!DOCTYPE html\u003e","\u003chtml\u003e","\u003chead\u003e","  \u003ctitle\u003eFile Unzipper + Zipper\u003c/title\u003e","  \u003cmeta http-equiv=\"Content-Type\" content=\"text/html; charset=UTF-8\"\u003e","  \u003cstyle type=\"text/css\"\u003e","    \u003c!--","    body {","      font-family: Arial, sans-serif;","      line-height: 150%;","    }","","    label {","      display: block;","      margin-top: 20px;","    }","","    fieldset {","      border: 0;","      background-color: #EEE;","      margin: 10px 0 10px 0;","    }","","    .select {","      padding: 5px;","      font-size: 110%;","    }","","    .status {","      margin: 0;","      margin-bottom: 20px;","      padding: 10px;","      font-size: 80%;","      background: #EEE;","      border: 1px dotted #DDD;","    }","","    .status--ERROR {","      background-color: red;","      color: white;","      font-size: 120%;","    }","","    .status--SUCCESS {","      background-color: green;","      font-weight: bold;","      color: white;","      font-size: 120%","    }","","    .small {","      font-size: 0.7rem;","      font-weight: normal;","    }","","    .version {","      font-size: 80%;","    }","","    .form-field {","      border: 1px solid #AAA;","      padding: 8px;","      width: 280px;","    }","","    .info {","      margin-top: 0;","      font-size: 80%;","      color: #777;","    }","","    .submit {","      background-color: #378de5;","      border: 0;","      color: #ffffff;","      font-size: 15px;","      padding: 10px 24px;","      margin: 20px 0 20px 0;","      text-decoration: none;","    }","","    .submit:hover {","      background-color: #2c6db2;","      cursor: pointer;","    }","    --\u003e","  \u003c/style\u003e","\u003c/head\u003e","\u003cbody\u003e","\u003cp class=\"status status--\u003c?php echo strtoupper(key($GLOBALS['status'])); ?\u003e\"\u003e","  Status: \u003c?php echo reset($GLOBALS['status']); ?\u003e\u003cbr/\u003e","  \u003cspan class=\"small\"\u003eProcessing Time: \u003c?php echo $time; ?\u003e seconds\u003c/span\u003e","\u003c/p\u003e","\u003cform action=\"\" method=\"POST\"\u003e","  \u003cfieldset\u003e","    \u003ch1\u003eArchive Unzipper\u003c/h1\u003e","    \u003clabel for=\"zipfile\"\u003eSelect .zip or .rar archive or .gz file you want to extract:\u003c/label\u003e","    \u003cselect name=\"zipfile\" size=\"1\" class=\"select\"\u003e","      \u003c?php foreach ($unzipper-\u003ezipfiles as $zip) {","        echo \"\u003coption\u003e$zip\u003c/option\u003e\";","      }","      ?\u003e","    \u003c/select\u003e","    \u003clabel for=\"extpath\"\u003eExtraction path (optional):\u003c/label\u003e","    \u003cinput type=\"text\" name=\"extpath\" class=\"form-field\" /\u003e","    \u003cp class=\"info\"\u003eEnter extraction path without leading or trailing slashes (e.g. \"mypath\"). If left empty current directory will be used.\u003c/p\u003e","    \u003cinput type=\"submit\" name=\"dounzip\" class=\"submit\" value=\"Unzip Archive\"/\u003e","  \u003c/fieldset\u003e","","  \u003cfieldset\u003e","    \u003ch1\u003eArchive Zipper\u003c/h1\u003e","    \u003clabel for=\"zippath\"\u003ePath that should be zipped (optional):\u003c/label\u003e","    \u003cinput type=\"text\" name=\"zippath\" class=\"form-field\" /\u003e","    \u003cp class=\