ppath\u003c/span\u003e\u0026#39;\u003c/span\u003e]) : \u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003e.\u003c/span\u003e\u0026#39;\u003c/span\u003e;","  \u003cspan class=pl-c\u003e// Resulting zipfile e.g. zipper--2016-07-23--11-55.zip.\u003c/span\u003e","  \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ezipfile\u003c/span\u003e = \u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003ezipper-\u003c/span\u003e\u0026#39;\u003c/span\u003e . \u003cspan class=pl-en\u003edate\u003c/span\u003e(\u003cspan class=pl-s\u003e\u0026quot;\u003cspan class=pl-s\u003eY-m-d--H-i\u003c/span\u003e\u0026quot;\u003c/span\u003e) . \u003cspan class=pl-s\u003e\u0026#39;\u003cspan class=pl-s\u003e.zip\u003c/span\u003e\u0026#39;\u003c/span\u003e;","  Zipper::\u003cspan class=pl-en\u003ezipDir\u003c/span\u003e(\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ezippath\u003c/span\u003e, \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003ezipfile\u003c/span\u003e);","}","","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003etimeend\u003c/span\u003e = \u003cspan class=pl-en\u003emicrotime\u003c/span\u003e(\u003cspan class=pl-c1\u003eTRUE\u003c/span\u003e);","\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003etime\u003c/span\u003e = \u003cspan class=pl-en\u003eround\u003c/span\u003e(\u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003etimeend\u003c/span\u003e - \u003cspan class=pl-s1\u003e\u003cspan class=pl-c1\u003e$\u003c/span\u003etimestart\u003c/span\u003e, \u003cspan class=pl-c1\u003e4\u003c/span\u003e);","","\u003cspan class=pl-c\u003e/**\u003c/span\u003e","\u003cspan class=pl-c\u003e * Class Unzipper\u003c/span\u003e","\u003cspan class=pl-c\u003e */\u003c/span\u003e","\u003cspan class=pl-k\u003eclass\u003c/span\u003e Unzipper {","  \u003cspan class=pl-k\u003epublic\u003c/span\u003e \u003cspan class=pl-c1\u003e\u003cspan class=pl-c